            "expected":
                int(
                    len(
                        section4ud_interface_profile_df
                    )
                ),
        },
        {
            "check":
                "configuration_valid",

            "passed":
                configuration_valid,

            "value":
                int(
                    section4ud_configuration_df[
                        "matches_expected"
                    ].sum()
                ),

            "expected":
                int(
                    len(
                        section4ud_configuration_df
                    )
                ),
        },
        {
            "check":
                "frozen_artifact_hashes_unchanged",

            "passed":
                all_artifacts_unchanged,

            "value":
                int(
                    section4ud_frozen_artifacts_df[
                        "artifact_unchanged"
                    ].sum()
                ),

            "expected":
                int(
                    len(
                        section4ud_frozen_artifacts_df
                    )
